import csv
import io

# Read the original file
with open('outputs/t08_pois_clean.csv', 'r') as f:
    content = f.read()

# Write to a new CSV reader that doesn't quote non-special fields
with open('outputs/t08_pois_clean.csv', 'r', newline='') as f:
    reader = csv.reader(f)
    rows = list(reader)

# Check if rows are properly formatted
header = rows[0]
print(f'Header: {header}')

for i, row in enumerate(rows[1:], 1):
    field_count = len(row)
    if field_count != len(header):
        print(f'Row {i}: Mismatch - {field_count} fields, expected {len(header)}')
    else:
        # Check for special characters that need quoting
        for j, field in enumerate(row):
            needs_quoting = False
            if ',' in field:
                needs_quoting = True
            if '\"' in field:
                needs_quoting = True
            if '\n' in field:
                needs_quoting = True

            if needs_quoting:
                # Check if it's already quoted
                if field.startswith('\"'):
                    # Check the content between quotes
                    content = field[1:-1]
                    if ',' in content or '\"' in content:
                        print(f'Row {i}, field {j}: {repr(field)} - content has special chars, is already quoted')
                    else:
                        print(f'Row {i}, field {j}: {repr(field)} - content has special chars, should be quoted')
                else:
                    print(f'Row {i}, field {j}: {repr(field)} - NOT quoted when it should be')
            else:
                print(f'Row {i}, field {j}: {repr(field[:50])}')
