        if char == '"':
            in_quote = not in_quote
            current += char
        elif char == ',':
            if not in_quote:
                parts.append(current)
                current = ''
        else:
            current += char
    if not in_quote:
        parts.append(current)

    lat = float(parts[3])
    lon = float(parts[4])
    if not (-90 <= lat <= 90):
        print(f'Invalid lat at row {i}: {lat}')
    if not (-180 <= lon <= 180):
        print(f'Invalid lon at row {i}: {lon}')

# Check for empty labels
for i, line in enumerate(lines[1:], 1):
    parts = []
    current = ''
    in_quote = False
    for char in line:
        if char == '"':
            in_quote = not in_quote
            current += char
        elif char == ',':
            if not in_quote:
                parts.append(current)
                current = ''
        else:
            current += char
    if not in_quote:
        parts.append(current)

    label = parts[1]
    if not label:
        print(f'Empty label at row {i}: {parts[0]}')

print('\nAll validations passed!')
